SELECT count(*) unit_rows,count(distinct facility_id) facility_ids,count(*) FILTER(WHERE county IN ('Ashland','Ashtabula','Columbiana','Cuyahoga','Erie','Geauga','Huron','Lake','Lorain','Mahoning','Medina','Portage','Richland','Stark','Summit','Trumbull','Tuscarawas','Wayne')) pic18_unit_rows,count(distinct facility_id) FILTER(WHERE county IN ('Ashland','Ashtabula','Columbiana','Cuyahoga','Erie','Geauga','Huron','Lake','Lorain','Mahoning','Medina','Portage','Richland','Stark','Summit','Trumbull','Tuscarawas','Wayne')) pic18_facility_ids FROM read_csv('/tmp/l5c-pbr.csv',all_varchar=true);
